#include <bits/stdc++.h>
using namespace std;
int main(){
    int M,N;
    while (cin >> M >> N) {
        vector<string> grid(M);
        for (auto &s: grid) cin >> s;
        int X,Y; cin >> X >> Y;
        char land='l';
        int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
        vector<vector<bool>> kingVis(M, vector<bool>(N,false));
        {
            queue<pair<int,int>> q; q.push({X,Y}); kingVis[X][Y]=true;
            while(!q.empty()){
                auto [x,y]=q.front(); q.pop();
                for(int d=0;d<4;d++){
                    int nx=x+dx[d], ny=(y+dy[d]+N)%N;
                    if(nx<0||nx>=M) continue;
                    if(kingVis[nx][ny]) continue;
                    if(grid[nx][ny]!=land) continue;
                    kingVis[nx][ny]=true; q.push({nx,ny});
                }
            }
        }
        vector<vector<bool>> seen(M, vector<bool>(N,false));
        int best=0;
        for(int i=0;i<M;i++) for(int j=0;j<N;j++){
            if (grid[i][j]!=land || seen[i][j] || kingVis[i][j]) continue;
            queue<pair<int,int>> q; q.push({i,j}); seen[i][j]=true;
            int size=0;
            while(!q.empty()){
                auto [x,y]=q.front(); q.pop(); size++;
                for(int d=0;d<4;d++){
                    int nx=x+dx[d], ny=(y+dy[d]+N)%N;
                    if(nx<0||nx>=M) continue;
                    if(seen[nx][ny]) continue;
                    if(grid[nx][ny]!=land) continue;
                    seen[nx][ny]=true; q.push({nx,ny});
                }
            }
            best=max(best,size);
        }
        cout << best << "\n";
    }
}

